-- Fynence core schema: private manual trading journal + user-owned settings.
CREATE TABLE IF NOT EXISTS public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text, timezone text NOT NULL DEFAULT 'Asia/Jakarta', theme text NOT NULL DEFAULT 'dark' CHECK (theme IN ('dark','light','system')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.trading_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 80), account_type text NOT NULL DEFAULT 'journal' CHECK (account_type IN ('journal','demo','manual')), base_currency text NOT NULL DEFAULT 'USD' CHECK (base_currency ~ '^[A-Z]{3}$'), initial_balance numeric(20,8), notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id));
CREATE INDEX IF NOT EXISTS trading_accounts_owner_idx ON public.trading_accounts(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS public.trades (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, account_id uuid, symbol text NOT NULL CHECK (length(trim(symbol)) BETWEEN 1 AND 32), direction text NOT NULL CHECK (direction IN ('long','short')), status text NOT NULL DEFAULT 'closed' CHECK (status IN ('open','closed')), opened_at timestamptz NOT NULL, closed_at timestamptz, entry_price numeric(30,12) NOT NULL CHECK (entry_price >= 0), exit_price numeric(30,12) CHECK (exit_price >= 0), size numeric(30,12) NOT NULL CHECK (size > 0), fees numeric(20,8) NOT NULL DEFAULT 0 CHECK (fees >= 0), realized_pnl numeric(20,8), stop_loss numeric(30,12), take_profit numeric(30,12), setup text, timeframe text, exit_reason text, notes text, setup_grade smallint CHECK (setup_grade BETWEEN 1 AND 5), execution_quality smallint CHECK (execution_quality BETWEEN 1 AND 5), plan_adherence boolean, emotion text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT trades_account_owner_fk FOREIGN KEY(account_id,user_id) REFERENCES public.trading_accounts(id,user_id) ON DELETE RESTRICT, CONSTRAINT trades_lifecycle_check CHECK ((status='open' AND closed_at IS NULL AND exit_price IS NULL AND realized_pnl IS NULL) OR (status='closed' AND closed_at IS NOT NULL AND exit_price IS NOT NULL AND closed_at >= opened_at)));
CREATE INDEX IF NOT EXISTS trades_owner_opened_idx ON public.trades(user_id,opened_at DESC);
CREATE INDEX IF NOT EXISTS trades_owner_status_opened_idx ON public.trades(user_id,status,opened_at DESC);
CREATE INDEX IF NOT EXISTS trades_account_opened_idx ON public.trades(account_id,opened_at DESC);
CREATE INDEX IF NOT EXISTS trades_owner_symbol_idx ON public.trades(user_id,symbol);
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.trading_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.trades ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.profiles,public.trading_accounts,public.trades TO authenticated;
CREATE POLICY profiles_select_own ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profiles_insert_own ON public.profiles FOR INSERT TO authenticated WITH CHECK (id=auth.uid());
CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE POLICY accounts_select_own ON public.trading_accounts FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY accounts_insert_own ON public.trading_accounts FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid());
CREATE POLICY accounts_update_own ON public.trading_accounts FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE POLICY accounts_delete_own ON public.trading_accounts FOR DELETE TO authenticated USING (user_id=auth.uid());
CREATE POLICY trades_select_own ON public.trades FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY trades_insert_own ON public.trades FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid());
CREATE POLICY trades_update_own ON public.trades FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE POLICY trades_delete_own ON public.trades FOR DELETE TO authenticated USING (user_id=auth.uid());
